SELECT rowid AS history_rowid, * FROM transactions INDEXED BY idx_transactions_date
         WHERE 1 = 1 
         ORDER BY date DESC, created_at DESC, rowid DESC LIMIT ?;

SELECT rowid AS history_rowid, * FROM transactions INDEXED BY idx_transactions_date
         WHERE 1 = 1 AND substr(date, 1, ?) = ? AND (account_id = ? OR (type <> 'internalTransfer' AND target_account_id = ?)) AND category_id = ? 
         ORDER BY date DESC, created_at DESC, rowid DESC LIMIT ?;

SELECT rowid AS history_rowid, id, date, created_at, merchant_name, description, notes FROM transactions INDEXED BY idx_transactions_date
         WHERE 1 = 1 AND ((instr(lower(merchant_name), ?) > 0 OR length(CAST(merchant_name AS BLOB)) <> length(merchant_name)) OR (instr(lower(description), ?) > 0 OR length(CAST(description AS BLOB)) <> length(description)) OR (instr(lower(notes), ?) > 0 OR length(CAST(notes AS BLOB)) <> length(notes))) 
         ORDER BY date DESC, created_at DESC, rowid DESC LIMIT ?;

